import { zodResolver } from '@hookform/resolvers/zod';
import clsx from 'clsx';
import { useEffect, useRef, useState } from 'react';
import { FormProvider, useForm } from 'react-hook-form';
//import { Inputs } from '~/entities/mobile-verification/model/types';
import { useLocation } from 'react-router-dom';
import { useSetHeaderTitle } from '~/widgets/sub-layout/use-sub-layout';
import { isPersonalBizNo } from '~/entities/business/lib/validate-biz-no';
import { Inputs } from '~/entities/business/model/types';
import { useCheckBizNoStatusMutation } from '~/entities/exchange/api/hooks/use-check-bizno-status-mutation';
import { useDeleteReceiptMutation } from '~/entities/exchange/api/hooks/use-delete-receipt-mutation';
import { useGetBizNoInformationMutation } from '~/entities/exchange/api/hooks/use-get-bizno-infomation-mutation';
import { useRegisterReceiptMutation } from '~/entities/exchange/api/hooks/use-register-receipt-mutation';
import { useGetUserInfoQuery } from '~/entities/user/api/use-get-cstmr-query';
import { RegisterBizNoFormSchema } from '~/entities/wallet/model/type';
import { StepBeforeRegister } from '~/shared/api/dtos/enums';
import { createFormOptions } from '~/shared/constants/form';
import i18n from '~/shared/i18n/i18n';
import { useNavigate } from '~/shared/lib/hooks';
import { useAlertDialog } from '~/shared/lib/hooks/use-alert-dialog';
import { notiBar } from '~/shared/lib/toast';
import { PATHS } from '~/shared/routes/paths';
import { closeDialog } from '~/shared/ui/dialogs';

type Props = {
  step?: StepBeforeRegister;
  aliasNm?: string;
  businessNumber?: string;
};

// 사업자등록번호 3-2-5 자리 (폼에는 10자리 문자열 하나로 저장한다)
const BIZ_NO_SEGMENTS = [3, 2, 5] as const;

const splitBizNo = (value?: string): string[] => {
  const digits = (value ?? '').replace(/[^0-9]/g, '');
  return [digits.slice(0, 3), digits.slice(3, 5), digits.slice(5, 10)];
};
export const BusinessAccountPage = () => {
  const { data: userRes, refetch: refetchUserInfo } = useGetUserInfoQuery();
  const { openAlertDialog } = useAlertDialog();
  const { navigate, navigateBack } = useNavigate();
  const { mutateAsync: receipt } = useRegisterReceiptMutation();
  const { mutateAsync: deleteReceipt } = useDeleteReceiptMutation();
  const { mutateAsync: checkBizNoStatus } = useCheckBizNoStatusMutation();
  const { mutateAsync: getBizNoInfo } = useGetBizNoInformationMutation();
  const { step, aliasNm, businessNumber } = ((useLocation().state as Props | null) ?? {}) as Props;
  const userBizNo = userRes?.tbCstmrMastr?.ewaBizNo;
  const cstmrNo = { cstmrNo: userRes?.tbCstmrMastr?.cstmrNo || '' };
  const formOptions = createFormOptions<Inputs>();

  const [isBusinessAccount] = useState<boolean>(step === StepBeforeRegister.재설정);
  const [SkipBtnFlag] = useState<boolean>(step === StepBeforeRegister.회원가입);
  const [isRegister] = useState<boolean>(step === StepBeforeRegister.등록);

  //true: from 회원가입 / false: from 재설정(마이페이지)

  const form = useForm<Inputs>({ mode: 'all', resolver: zodResolver(RegisterBizNoFormSchema) });
  const { register, handleSubmit, getValues, setValue, watch } = form;

  useSetHeaderTitle(i18n.t('manageBusinessAccount'));

  // 관리 화면은 조회한 값이 채워진 채로 진입하므로, 네 칸이 모두 차 있으면 등록 버튼을 연다
  const isAllFilled = watch(['businessNumber', 'bizName', 'ownerName', 'openDate']).every(
    (value) => (value ?? '').trim().length > 0,
  );

  const [bizNoSegments, setBizNoSegments] = useState<string[]>(() => splitBizNo(businessNumber));
  const bizNoRefs = useRef<(HTMLInputElement | null)[]>([]);

  const handleBizNoChange = (index: number) => (event: React.ChangeEvent<HTMLInputElement>) => {
    const value = event.target.value.replace(/[^0-9]/g, '').slice(0, BIZ_NO_SEGMENTS[index]);
    const next = bizNoSegments.map((item, i) => (i === index ? value : item));

    setBizNoSegments(next);
    setValue('businessNumber', next.join(''), { shouldValidate: true });

    if (value.length === BIZ_NO_SEGMENTS[index]) {
      bizNoRefs.current[index + 1]?.focus();
    }
  };

  const handleBizNoKeyDown = (index: number) => (event: React.KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Backspace' && !bizNoSegments[index] && index > 0) {
      bizNoRefs.current[index - 1]?.focus();
    }
  };

  //유저 정보 갱신
  const syncUserInfo = async () => {
    await refetchUserInfo();
  };

  // 등록/변경 요청 실패 시 공통으로 띄우는 안내 팝업
  const showRegisterFailDialog = () => {
    openAlertDialog({
      title: i18n.t('notification'),
      message: i18n.t('validation:failRegisterBizNo'),
    });
  };

  const onSubmit = () => {
    const param = {
      ewaBizNo: getValues('businessNumber') || '',
      bizName: getValues('bizName'),
      ownerName: getValues('ownerName') || '',
      openDate: getValues('openDate') || '',
      aliasNm: aliasNm || '',
    };

    //if (!fnValidation(param)) return;

    setTimeout(async () => {
      openAlertDialog({
        message: '입력하신 정보로 등록하시겠습니까?',
        buttonLabel: [i18n.t('cancel'), i18n.t('confirm')],
        onConfirmClick: async () => {
          //개인사업자인지 check
          const isPersonalBiz = isPersonalBizNo(param.ewaBizNo);
          if (!isPersonalBiz) {
            openAlertDialog({
              message: i18n.t('text:personalBusinessOnly'),
              onConfirmClick: () => {
                return;
              },
            });

            return;
          }

          try {
            await receipt(param);
            await syncUserInfo();
          } catch {
            showRegisterFailDialog();
            return;
          }

          // 완료 화면이 같은 내용을 안내하므로 토스트는 띄우지 않는다
          navigate(PATHS.myWallet.businessComplete, { replace: true });
        },
        onCancelClick: () => {
          //아무것도 수행하지 않음
        },
      });
    }, 0);
  };

  const requestRegisterBizNo = async () => {
    //const params: string = '1168119477';
    const param = {
      ewaBizNo: getValues('businessNumber') || '',
      bizName: getValues('bizName') || '',
      ownerName: getValues('ownerName') || '',
      openDate: getValues('openDate') || '',
    };

    openAlertDialog({
      title: i18n.t('changeBusinessAccount'),
      message: i18n.t('validation:changeBusinessInfoConfirmation'),
      buttonLabel: [i18n.t('cancel'), i18n.t('change')],
      onConfirmClick: async () => {
        //개인사업자인지 check
        const isPersonalBiz = isPersonalBizNo(param.ewaBizNo);
        if (!isPersonalBiz) {
          openAlertDialog({
            message: i18n.t('text:personalBusinessOnly'),
            onConfirmClick: () => {
              return;
            },
          });

          return;
        }

        setTimeout(async () => {
          //사업자정보변경은 신규등록
          try {
            await receipt(param);
            await syncUserInfo();
          } catch {
            showRegisterFailDialog();
            return;
          }

          notiBar(i18n.t('completeChangeBizNo'));
          navigateBack();
        }, 0);
      },
      onCancelClick: () => {
        // 취소 시 아무 작업 없음
      },
    });
    //return await receipt(params);
  };

  const handleDeleteBizNo = () => {
    openAlertDialog({
      title: i18n.t('deleteBusinessAccount'),
      message: i18n.t('validation:deleteBusinessInfoConfirmation'),
      buttonLabel: [i18n.t('cancel'), i18n.t('delete')],
      onConfirmClick: async () => {
        await deleteReceipt(cstmrNo);
        await syncUserInfo();
        notiBar(i18n.t('completeDeleteBizNo'));
        navigateBack();
      },
      onCancelClick: () => {
        // 취소 시 아무 작업 없음
      },
    });
  };

  const handleSkip = () => {
    openAlertDialog({
      title: '사업자 등록 건너뛰기',
      message: '사업자 등록을 취소하시겠습니까?',
      buttonLabel: [i18n.t('cancel'), i18n.t('confirm')],
      onConfirmClick: () => {
        closeDialog(() => {
          navigate(PATHS.home, { replace: true });
        });
      },
      onCancelClick: () => {
        // 취소 시 아무 작업 없음
      },
    });
  };

  useEffect(() => {
    // 사업자등록번호 입력 화면에서 넘어온 경우 해당 값으로 시작한다
    if (businessNumber) {
      setValue('businessNumber', businessNumber, { shouldValidate: true });
    }
  }, [businessNumber, setValue]);

  useEffect(() => {
    //userRes에 bizno가 있으면 status 검색
    if (isBusinessAccount) {
      setTimeout(async () => {
        //await checkBizNoStatus('1168119477').then((response) => {
        await getBizNoInfo(userBizNo).then((response) => {
          setValue('businessNumber', response.ewaBizNo, { shouldValidate: true });
          setValue('bizName', response.bizName, { shouldValidate: true });
          setValue('ownerName', response.ownerName, { shouldValidate: true });
          setValue('openDate', response.openDate, { shouldValidate: true });
          setBizNoSegments(splitBizNo(response.ewaBizNo));
        });
      }, 0);
    }
  }, []);

  return (
    <div className="page-business-register-KBB has-fixed-bottom">
      <div className="business-register-main">
        <section className="business-register-title-container">
          <h2 className="page-title">
            {isBusinessAccount ? i18n.t('manageBusinessAccount') : i18n.t('createBusinessAccount')}
          </h2>
        </section>

        <section className="business-register-guide-box">
          <ul className="guide-list">
            <li className="guide-item">현금영수증을 발급하려면 반드시 현금영수증 가맹점 가입이 필요합니다.</li>
            <li className="guide-item">가맹점 가입은 금융결제원 e서비스(kftcvan.or.kr) 에서 가능합니다.</li>
            <li className="guide-item">
              현금영수증 의무발행은 의무발행업종 사업자가 건당 10만원 이상 현금거래 시 소비자가 요구하지 않아도
              자진발급(010-000-1234) 해야 하며, 미발급 시 20% 가산세가 부과됩니다.
            </li>
          </ul>
        </section>

        <FormProvider {...form}>
          <form onSubmit={handleSubmit(onSubmit)} className="business-register-form-container">
            <div className="form-item">
              <label className="form-label" htmlFor="bizNum1">
                {i18n.t('businessNumber')}
              </label>
              <div className="business-number-inputs">
                {BIZ_NO_SEGMENTS.map((length, index) => (
                  <div key={length} className={clsx('input-item', 'common-input-field', `flex-${index + 1}`)}>
                    <input
                      type="text"
                      inputMode="numeric"
                      id={`bizNum${index + 1}`}
                      className="common-form-input"
                      placeholder={`${length}자리`}
                      maxLength={length}
                      value={bizNoSegments[index]}
                      onChange={handleBizNoChange(index)}
                      onKeyDown={handleBizNoKeyDown(index)}
                      ref={(element) => (bizNoRefs.current[index] = element)}
                    />
                  </div>
                ))}
              </div>
            </div>

            <div className="form-item">
              <label className="form-label" htmlFor="bizName">
                {i18n.t('bizName')}
              </label>
              <div className="common-input-field">
                <input
                  type="text"
                  id="bizName"
                  className="common-form-input kbfg-text"
                  placeholder="상호명을 입력하세요"
                  {...register('bizName')}
                />
              </div>
            </div>

            <div className="form-item">
              <label className="form-label" htmlFor="ownerName">
                {i18n.t('name')}
              </label>
              <div className="common-input-field">
                <input
                  type="text"
                  id="ownerName"
                  className="common-form-input kbfg-text"
                  placeholder="이름을 입력하세요"
                  {...register('ownerName')}
                />
              </div>
            </div>

            <div className="form-item">
              <label className="form-label" htmlFor="openDate">
                {i18n.t('openDate')}
              </label>
              <div className="common-input-field">
                <input
                  type="text"
                  inputMode="numeric"
                  id="openDate"
                  className="common-form-input"
                  placeholder="8자리(YYYYMMDD)"
                  maxLength={8}
                  {...register('openDate')}
                />
              </div>
            </div>

            {isBusinessAccount && (
              <div className="business-manage-action-area">
                <div className="notice-info">
                  <i className="icon-info-circle" aria-hidden="true"></i>
                  <p className="notice-text">사업자 정보 삭제 시, 현금영수증 발급이 불가합니다.</p>
                </div>
                <button type="button" className="btn-delete-business" onClick={handleDeleteBizNo}>
                  <i className="icon-setting" aria-hidden="true"></i>
                  <span className="btn-text">{i18n.t('deleteBusinessAccount')}</span>
                  <i className="icon-arrow-right" aria-hidden="true"></i>
                </button>
              </div>
            )}
          </form>
        </FormProvider>
      </div>

      <div className="fixed-bottom-btn-wrapper">
        {SkipBtnFlag && (
          <button type="button" className="btn-confirm-bottom" onClick={handleSkip}>
            {i18n.t('skip')}
          </button>
        )}
        <button
          type="button"
          className={clsx('btn-confirm-bottom', !isAllFilled && 'disabled')}
          disabled={!isAllFilled}
          onClick={isBusinessAccount ? requestRegisterBizNo : handleSubmit(onSubmit)}
        >
          {i18n.t('register')}
        </button>
      </div>
    </div>
  );
};
